// A module of a package named `effect`, so the pass type-models it from its `.d.ts`.
import { importedBase } from './base.js';

// Immutable aliases: every hop is a top-level const, so each export is its key.
const aliasedBase = 'aliasedKey';
const aliasedHop = aliasedBase;
export const aliased = aliasedHop;
export const viaImport = importedBase;
export { reexported } from './base.js';

// Mutable aliases: each starts from a const literal, but a write changes it.
const letInitial = 'letFirst';
export let reassignedLet = letInitial;
reassignedLet = 'letSecond';

const varInitial = 'varFirst';
export var reassignedVar = varInitial;
reassignedVar = 'varSecond';

const hopInitial = 'hopFirst';
let hop = hopInitial;
hop = 'hopSecond';
export const throughLet = hop;
